1/* Import font */
2@import url("https://fonts.googleapis.com/css2?family=Euclid+Circular+A:wght@400;500&display=swap");
3@import url('https://fonts.googleapis.com/css2?family=Galdeano&display=swap');
4
5/* Reset browser's default styles */
6* {
7    padding: 0;
8    margin: 0;
9    box-sizing: border-box;
10    line-height: 1.5;
11    font-family: 'Euclid Circular A', sans-serif;
12    /* border: 1px solid red; */
13}
14
15/* Contain image */
16img {
17    max-width: 100%;
18    height: auto;
19}
20
21/* -------------- */
22.header,
23.footer {
24    background-color: #2c2e48;
25    min-height: 50px;
26}
27
28
29.main section:nth-child(odd) {
30    background-color: #c6b6d7;
31}
32
33/* ---------- Common styles ---------- */
34.main>section {
35    display: flex;
36    flex-direction: column;
37    align-items: center;
38    justify-content: center;
39    min-height: 300px;
40    padding: 80px;
41    gap: 32px;
42}
43
44section h2 {
45    color: #25265e;
46    font-size: 32px; 
47    font-weight: 600; 
48    text-align: center; 
49}
50
51section p {
52    color: #25265e;
53    font-size: 18px;
54    font-weight: 300;
55}
56
57/* ---------- Header section ---------- */
58.header {
59    display: flex;
60    padding: 10px min(5vw, 300px);
61    justify-content: space-between;
62    align-items: center;
63
64}
65
66.logo {
67    font-size: 32px;
68    font-weight: 400;
69    font-family: Galdeano, sans-serif;
70    color: white;
71}
72
73.nav {
74    display: flex;
75    gap: 24px;
76}
77
78.nav a {
79    text-decoration: none;
80    color: white;
81    font-size: 16px;
82    letter-spacing: 1px;
83}
84
85/* ---------- Hero section ---------- */
86section.hero {
87    display: flex;
88    flex-direction: column;
89    align-items: center;
90    justify-content: center;
91    gap: 8px;
92
93    min-height: 500px;
94    text-align: center;
95}
96
97section.hero img {
98    width: 200px;
99    height: 200px;
100    border-radius: 50%;
101    object-fit: cover;
102    margin-bottom: 20px;
103    border: 2px solid white;
104}
105
106section.hero h3 {
107    font-size: 32px;
108    font-weight: 600;
109    color: #25265e;
110}
111
112section.hero p {
113    font-size: 18px;
114    letter-spacing: 1px;
115    margin-bottom: 10px;
116    font-weight: 400;
117    color: #25265e;
118    text-transform: uppercase;
119}
120
121/* ---------- About section ---------- */
122section.about {
123    display: flex;
124    flex-direction: column;
125    padding: min(10vw, 160px) min(10vw, 120px);
126    text-align: center;
127    justify-content: center;
128    align-items: center;
129    gap: 32px;
130}
131
132/* ---------- Blogs section ---------- */
133.blogs {
134    display: flex;
135    flex-direction: column;
136    align-items: center;
137    justify-content: center;
138    gap: 32px;
139    padding: 80px;
140    text-align: center;
141    background-color: #d1c4e9;    /* Same background color as Hero section */
142}
143
144/* Card Container */
145.card-row {
146    display: flex;
147    flex-wrap: wrap;    /* Allow the cards to wrap on smaller screens */
148    justify-content: center;    /* Center the cards horizontally */
149    gap: 20px;    /* Space between the cards */
150    margin: 40px auto;    /* Center the container */
151    padding: 0 20px;    /* Padding on the sides */
152    max-width: 1200px;    /* Ensure it doesn't stretch too wide */
153}
154
155/* Blog card styling */
156.card {
157    background-color: white;
158    border-radius: 8px;    /* Rounded corners */
159    box-shadow: 0 3px 4px rgba(0, 0, 0, 0.1);    /* Subtle shadow */
160    width: 300px;    /* Fixed width */
161    text-align: center;
162    display: flex;
163    flex-direction: column;    /* Stack content vertically */
164    gap: 4px;    /* Small gap between content */
165    align-items: center;
166    padding: 24px 0;    /* Adds padding */
167}
168
169/* Blog card image */
170.card img {
171    border-radius: 50%;    /* Circular image */
172    width: 192px;
173    height: 192px;
174    object-fit: cover;    /* Ensures image fits the circle */
175    margin-bottom: 16px;    /* Space below the image */
176}
177
178/* Blog card title */
179.card h3 {
180    color: #25265e;
181    font-weight: 700;
182    font-size: max(1vw, 18px);
183    text-decoration: none;
184}
185
186/* Blog card source */
187.card p {
188    font-size: 1rem;
189    color: #444576;
190}
191
192/* Read button */
193.card button {
194    padding: 8px 30px;
195    background-color: #0556f3;    /* Button background color */
196    color: white;    /* Button text color */
197    border: none;
198    border-radius: 4px;
199    cursor: pointer;
200    margin-top: 24px;
201}
202
203/* Button hover effect */
204.card button:hover {
205    background-color: #6c6ce5;    /* Button color on hover */
206}
207
208/* ---------- Projects section ---------- */
209.projects-grid {
210    display: grid;
211    grid-template-columns: 2fr 1fr 1fr;
212    grid-template-rows: auto auto;
213    gap: 20px;
214}
215
216/* Style cards */
217.projects-grid > div {
218    background-color: #ffffff;
219    border-radius: 10px;
220    padding: 20px;
221    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
222}
223
224.primary-card {
225    grid-area: 1 / 1 / 3 / 2;
226}
227
228/* Flex layout */
229.tech-tag-list {
230    display: flex;
231    gap: 10px;
232}
233
234/* Style tags */
235.tech-tag-list > div {
236    background-color: #f3f3f3;
237    color: #49497e;
238    font-size: 0.8rem;
239    border-radius: 5px;
240    padding: 4px 4px;
241}
242
243/* Style images */
244img {
245    width: 100%;
246    border-radius: 10px;
247}
248
249/* Style headings */
250h3 {
251    color: #25265e;
252    font-size: 1.5rem;
253    font-weight: 550;
254}
255
256/* Style paragraphs */
257p {
258    font-size: 16px;
259}
260
261/* Style links */
262a {
263    color: #0556f3;
264    font-weight: medium;
265    text-decoration: none;
266}
267
268/* Mobile view */
269@media (max-width: 768px) {
270    .projects-grid {
271        display: flex;
272        flex-direction: column;
273        align-items: center;
274        justify-content: center;
275    }
276
277    .tech-tag-list,
278    .projects-card p {
279        display: none;
280    }
281
282    .projects-card {
283        display: flex;
284        flex-direction: column;
285        align-items: center;
286    }
287}
288
289/* ---------- Contact section ---------- */
290.contact {
291    padding: 80px;
292}
293
294.contact-form-container {
295    border-radius: 12px;
296    width: 100%;
297    max-width: 1180px;
298}
299
300.contact h2 {
301    margin-bottom: 32px;
302}
303
304.form-row {
305    display: flex;
306    justify-content: space-between;
307    gap: 20px;
308}
309
310.form-group {
311    margin-bottom: 30px;
312    flex: 1;
313}
314
315.form-group label {
316    font-size: 18px;
317    color: #25265e;
318    display: block;
319    margin-bottom: 5px;
320}
321
322.form-group input,
323.form-group select,
324.form-group textarea {
325    width: 100%;
326    height: 42px;
327    padding: 8px;
328    border-radius: 6px;
329    border: 1px solid #ccc;
330    font-size: 16px;
331    background-color: #ffffff;
332    color: #25265e;
333}
334
335.form-group textarea {
336    height: auto;
337}
338
339.form-group input::placeholder,
340.form-group textarea::placeholder {
341    color: #a0a0b0;
342}
343
344.form-group input:focus,
345.form-group select:focus,
346.form-group textarea:focus {
347    border-color: #c6b8f5;
348    outline: none;
349}
350
351.submit-btn {
352    display: block;
353    padding: 8px 30px;
354    background-color: #0556f3;
355    color: white;
356    font-size: 16px;
357    border: none;
358    border-radius: 6px;
359    margin-left: auto;
360}
361
362.submit-btn:hover {
363    background-color: #7e58cc;
364}
365
366/* Media query for small screens */
367@media (max-width: 380px) {
368    .form-row {
369        flex-direction: column;
370        /* Stack the input fields */
371    }
372
373    .form-group input,
374    .form-group select,
375    .form-group textarea {
376        width: 100%;
377        /* Ensure input fields take full width */
378    }
379
380    .contact-form-container {
381        padding: 20px;
382        /* Reduced padding for smaller screens */
383        margin: 0 20px;
384        /* Margin adjustment for smaller screens */
385    }
386
387    h1 {
388        font-size: 20px;
389        /* Smaller heading for mobile */
390    }
391
392    .submit-btn {
393        width: 100%;
394        /* Submit button takes full width */
395        margin-left: 0;
396        /* Remove auto left margin */
397    }
398}
399
400/* Media query for small screens */
401@media (max-width: 600px) {
402    .form-row {
403        flex-direction: column;
404        /* Stack the input fields */
405    }
406
407    .form-group input,
408    .form-group select,
409    .form-group textarea {
410        width: 100%;
411        /* Ensure input fields take full width */
412    }
413
414    .contact-form-container {
415        padding: 20px;
416        /* Reduced padding for smaller screens */
417    }
418
419    h1 {
420        font-size: 20px;
421        /* Smaller heading for mobile */
422    }
423
424    .submit-btn {
425        width: 100%;
426        /* Submit button takes full width */
427        margin-left: 0;
428        /* Remove auto left margin */
429    }
430}
431
432/* ---------- Footer section ---------- */
433.footer {
434    background-color: #2c2e48;
435    text-align: center;
436    color: #ffffff;
437    display: flex;
438    justify-content: space-between;
439    align-items: center;
440    padding: 10px 40px;
441    /* Increased left and right padding */
442}
443
444.footer-text {
445    font-size: 16px;
446    margin: 0;
447}
448
449.heart {
450    color: red;
451}
452
453.footer-logos {
454    display: flex;
455    gap: 10px;
456    color: inherit;
457}
458
459.footer-logos img {
460    width: 20px;
461    height: 20px;
462}
